const payload = $input.first().json.body || $input.first().json;

if (!payload || !payload.students) {
  return [{ json: { error: 'Invalid or empty payload received' } }];
}

const meta = payload.meta || {};
const students = payload.students || [];
const attendance = payload.attendance || {};
const scores = payload.scores || {};

const results = students.map(student => {
  const sId = student.id;

  const t1 = (scores.term1 && scores.term1[sId]) || {};
  const t2 = (scores.term2 && scores.term2[sId]) || {};
  const t3 = (scores.term3 && scores.term3[sId]) || {};

  let p1 = 0, a1 = 0;
  if (attendance.term1 && attendance.term1[sId]) {
    attendance.term1[sId].forEach(st => {
      if (st === 'present') p1++; 
      else if (st === 'absent') a1++; 
    });
  }

  return {
    json: {
      Year: meta.year,
      Class: meta.className,
      Subject: meta.subject,
      Teacher: meta.teacher,
      SyncTime: meta.timestamp,
      StudentName: student.name || 'Unnamed Student',
      T1_CA1: t1.ca1, T1_CA2: t1.ca2, T1_CA3: t1.ca3, T1_CA4: t1.ca4, T1_Exam: t1.exam,
      T2_CA1: t2.ca1, T2_CA2: t2.ca2, T2_CA3: t2.ca3, T2_CA4: t2.ca4, T2_Exam: t2.exam,
      T3_CA1: t3.ca1, T3_CA2: t3.ca2, T3_CA3: t3.ca3, T3_CA4: t3.ca4, T3_Exam: t3.exam,
      T1_DaysPresent: p1, T1_DaysAbsent: a1
    }
  };
});

return results;
